"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8957],{1264:e=>{e.exports=JSON.parse('{"tag":{"label":"Sensors & Instrumentation","permalink":"/science/tags/sensors-instrumentation","allTagsPath":"/science/tags","count":7,"items":[{"id":"2025/autonomous-camera-control","title":"An Autonomous Camera Control System Inspired by Curiosity","description":"Author: Yufeng Luo, MCS Research Aide, University of Wyoming, Summer 2024","permalink":"/science/2025/autonomous-camera-control"},{"id":"2023/lightning-detector","title":"Lightning Detection with Software Defined Radio","description":"Lightning causes significant damage, starts wildfires, and poses a threat to human safety. Lightning strike releases a large pulse of electromagnetic energy that can be detected and recorded with software-defined radio (SDR). These recordings can be used to:","permalink":"/science/2023/lightning-detector"},{"id":"2023/lightning-science","title":"Lightning Science","description":"Overview","permalink":"/science/2023/lightning-science"},{"id":"2023/monitoring-biodiversity","title":"Monitoring biodiversity using acoustic data","description":"The Big Picture","permalink":"/science/2023/monitoring-biodiversity"},{"id":"2026/halow","title":"Sage-HaLow \u2014 First-Pass Summary","description":"Authors: Ben Owusu-Amo and Hairik Honarchian Saki (Colorado State University)","permalink":"/science/2026/halow"},{"id":"2023/scalable-ci-in-aps","title":"Scalable AI@Edge Computing in X-ray Beamline Experiments","description":"Can Edge Computing Be Used in X-Ray Beamline Experiments to Process a High-Volume and Fast Data Stream and Help Scientists Make Real-Time Decisions for Experiments?","permalink":"/science/2023/scalable-ci-in-aps"},{"id":"2024/lidar-sky-solar","title":"Using LIDAR to Aid Models in Solar Estimation and Sky Classification","description":"LIDAR technology, with its ability to create detailed maps of atmospheric environments, can potentially solve the issue of blockers by providing precise information about the location and height of obstructions. It proposes many benefits that can\u2019t be offered by a regular camera, especially the fact that it provides accurate data in all different types of weather conditions including fog, rain, and low light. This information can be used to adjust solar irradiance estimates and sky predictions, making them more accurate in any setting. Current models experience difficulties in the presense of blockers and unfamiliar sky conditions. We believe LiDAR can potentially solve this issue and allow us to deploy these nodes in urban areas.","permalink":"/science/2024/lidar-sky-solar"}],"unlisted":false}}')}}]);